import{_ as t,o as e,c as p,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Types-of-Commands.md","filePath":"manual-zh/Types-of-Commands.md","lastUpdated":1785684581000}'),r={name:"manual-zh/Types-of-Commands.md"};function s(n,a,m,d,_,f){return e(),p("div",null,[...a[0]||(a[0]=[o('<h3 id="_6-4-命令的类型" tabindex="-1">6.4 命令的类型 <a class="header-anchor" href="#_6-4-命令的类型" aria-label="Permalink to &quot;6.4 命令的类型&quot;">​</a></h3><p>PSPP 中的命令大致分为六类：</p><p><strong>实用命令</strong></p><p>设置或显示影响 PSPP 运行的各种全局选项。可以出现在语法文件中的任意位置。见 <a href="./Utilities">实用命令</a>。</p><p><strong>文件定义命令</strong></p><p>提供从文本文件或特殊的二进制“系统文件”读取数据的指令。这些命令大多会用新的数据或变量替换任何先前的数据或变量。在下面任一类别的第一个命令之前，必须至少出现一个文件定义命令。见 <a href="./Data-Input-and-Output">数据输入与输出</a>。</p><p><strong>输入程序命令</strong></p><p>虽然很少使用，但这些命令提供了以任意文本或二进制格式读取数据文件的工具。见 <a href="./INPUT-PROGRAM">INPUT PROGRAM</a>。</p><p><strong>变换</strong></p><p>对数据执行操作并将数据写入输出文件。变换要到过程执行时才会进行。</p><p><strong>受限变换</strong></p><p>不能出现在某些上下文中的变换。详情见 <a href="./Order-of-Commands">命令的顺序</a>。</p><p><strong>过程</strong></p><p>分析数据，将分析结果写入列表文件。会导致文件中较早指定的变换被执行。在更一般的意义上，<em>过程</em> 是任何导致活动数据集（即数据）被读取的命令。</p>',14)])])}const c=t(r,[["render",s]]);export{l as __pageData,c as default};
